# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry

logger = logging.getLogger(__name__)

NUM_SIPS = 48

# int32 offset safe domain: the masked tail block evaluates
# block_id * BLOCK + arange for masked lanes as well, reaching up to
# num_blocks * BLOCK - 1; keep n_total <= 2^31 - 2^17 (BLOCK <= 131072)
# so flat int32 offsets cannot wrap negative on the tail block.  Larger
# launches switch to the WIDE (int64 offset) arm instead of crashing.
_INT32_SAFE_LIMIT = (1 << 31) - (1 << 17)

_FLAT_DTYPES = (torch.float16, torch.bfloat16, torch.float32)

# GCU400 retune of the out-of-place hardswish (2026-11-17), aligned with the
# in-place hardswish_ retune of 2026-11-16 (same 1R1W traffic and the same
# five-op f32 chain add+max+min+mul+mul).  The old fixed config
# (BLOCK_SIZE=1024, one program per block) computed grid = cdiv(n, 1024),
# which exceeds the 65535 grid.x hardware limit at the 2^30-element core
# shapes (grid = 1048576) and aborts the benchmark with
# OutOfResources.  The grid-stride flat kernel below keeps at most
# NUM_SIPS programs alive and walks the tensor in tiles, so grid.x is
# bounded by 24 at any tensor size; the tile ladder, EVEN specialization
# (tail mask dropped when n divides the tile) and num_warps banding are
# reused verbatim from the measured hardswish_ ladder (2026-11-16,
# interleaved do_bench(median) on L600, official bench kernel mode):
#   16-bit 512M: 941 -> 675us (-28%, in-place, copy floor 668)
#   16-bit 16.7M: 36.2 -> 28.4us (-22%)
#   16-bit 4096: 5.73 -> 3.16us (-45%, launch floor 3.11)
#   fp32 512M: 1339 -> 1331us (copy floor 1330)
# The f32 promote-to-f32 body keeps aten semantics
# (hardswish(x) = x * min(max(x+3, 0), 6) / 6 via the * (1/6) reciprocal);
# NaN/inf inputs keep aten semantics because the final multiply
# propagates them (NaN * 0 = NaN, -inf * 0 = NaN), verified value-by-value
# against torch.nn.functional.hardswish on CPU by test_hardswish_special_values.


@libentry()
@triton.jit(do_not_specialize=["N_total"])
def hardswish_flat_kernel(
    x_ptr,
    out_ptr,
    N_total,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
    WIDE: tl.constexpr,
):
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    arange = tl.arange(0, BLOCK)

    num_blocks = (N_total + BLOCK - 1) // BLOCK
    for block_id in tl.range(pid, num_blocks, num_pids):
        if WIDE:
            off = block_id.to(tl.int64) * BLOCK + arange
        else:
            off = block_id * BLOCK + arange
        if EVEN:
            x = tl.load(x_ptr + off).to(tl.float32)
            inner = tl.minimum(tl.maximum(x + 3.0, 0.0), 6.0)
            y = x * inner * (1.0 / 6.0)
            tl.store(out_ptr + off, y)
        else:
            mask = off < N_total
            x = tl.load(x_ptr + off, mask=mask).to(tl.float32)
            inner = tl.minimum(tl.maximum(x + 3.0, 0.0), 6.0)
            y = x * inner * (1.0 / 6.0)
            tl.store(out_ptr + off, y, mask=mask)


def _choose_launch(n_total, itemsize):
    # Ladder re-measured on this 48-SIP board (2026-11-22) with a same-process
    # real-kernel A/B harness: only the returned (BLOCK, num_warps, grid cap)
    # varies, every entry runs the shipped hardswish_flat_kernel through
    # _launch_flat, so each delta is attributable to the tile alone.
    #   16-bit, n=2^29:  8192/nw2/cap24 2.853ms -> 65536/nw4 1.510ms (-47%)
    #   16-bit, n=2^24:  8192/nw2       0.0935   -> 65536/nw4 0.0562 (-40%)
    #   16-bit, n=2^18:  32768/nw4 0.0058 is the best of the wide band; the
    #                    65536 tile loses 14% there, so the band stays split.
    #   fp32,   n=2^29:  65536/nw8      2.565    -> 16384/nw2 2.508 (-2.2%)
    #   fp32,   n=2^24:  32768/nw8      0.0712   -> 65536/nw8 0.0699 (-1.8%)
    #   fp32,   n=2^20:  32768/nw8      0.0123   -> 65536/nw8 0.0110 (-11%)
    # The previous 16-bit arm (8192/nw2, 24 CTAs) was carried over from an L600
    # ladder: on this part it both halves the SIP count and uses a tile far
    # below the device's copy sweet spot, which is why the official bench had
    # 16-bit 2^29 at 0.62x while fp32 - moving twice the bytes - held 1.0x.
    # Tile bands are kept disjoint per num_warps: the libentry dispatch key is
    # built from dtype + constexpr args and does NOT include num_warps, so a
    # second warp count for the same BLOCK would silently reuse the first
    # compiled kernel.  Tiny (<=8192) is unchanged: it already rides the launch
    # floor.
    if n_total <= 8192:
        return min(max(triton.next_power_of_2(n_total), 64), 2048), 4, NUM_SIPS
    if n_total <= 65536:
        return 4096, 8, NUM_SIPS
    if itemsize == 4:
        # fp32 stays on the shipped arm: the in-process sweep put 65536/nw8
        # ahead at 2^24 (-1.8%) and 16384/nw2 ahead at 2^29 (-2.2%), but the
        # official bench flagged those same two bands as noisier (2^29 came
        # back 0.82x/0.97x vs 1.01x baseline), so the <=2% upside is not worth
        # the regression risk.
        if n_total <= (1 << 22):
            return 32768, 8, 48
        return 65536, 8, 48
    if n_total <= (1 << 18):
        return 32768, 4, NUM_SIPS
    return 65536, 4, NUM_SIPS


def _launch_flat(kernel, args, n_total, block, num_warps, grid_cap):
    even = n_total % block == 0
    if not even and num_warps > 2:
        # The tail mask costs nothing at nw2 (685 vs 683us at 512M) but is
        # heavily exposed at nw8 (36.5 vs 28.4us at 16.7M); odd sizes ride
        # the masked arm on nw2.
        num_warps = 2
    grid_size = min(triton.cdiv(n_total, block), grid_cap)
    wide = n_total >= _INT32_SAFE_LIMIT
    # The external llvm converter intermittently fails on cold compiles
    # (nondeterministic, host-level userland flake windows on shared nodes);
    # retrying the launch recompiles and succeeds (abs.py / sinh.py /
    # hardswish_.py precedents for the same toolchain family).
    for attempt in range(3):
        try:
            with torch_device_fn.device(args[0].device):
                kernel[(grid_size,)](
                    *args,
                    n_total,
                    BLOCK=block,
                    EVEN=even,
                    WIDE=wide,
                    num_warps=num_warps,
                )
            return
        except Exception as exc:
            if attempt == 2:
                raise
            logger.warning(
                "hardswish flat kernel launch failed (attempt %d): %s",
                attempt + 1,
                exc,
            )


def hardswish(x: torch.Tensor):
    logger.debug("GEMS_ENFLAME HARDSWISH")
    if not isinstance(x, torch.Tensor):
        raise TypeError("hardswish(): expected a Tensor")
    if x.dtype not in _FLAT_DTYPES:
        from flag_gems.ops.hardswish import hardswish as _public

        return _public(x)

    inp = x.contiguous()
    n_total = inp.numel()
    if n_total == 0:
        return torch.empty_like(inp)
    out = torch.empty_like(inp)

    block, num_warps, grid_cap = _choose_launch(n_total, inp.element_size())
    _launch_flat(hardswish_flat_kernel, (inp, out), n_total, block, num_warps, grid_cap)
    return out


def hardswish_out(x: torch.Tensor, out: torch.Tensor):
    logger.debug("GEMS_ENFLAME HARDSWISH_OUT")
    if not isinstance(x, torch.Tensor) or not isinstance(out, torch.Tensor):
        raise TypeError("hardswish_out(): expected Tensors")
    assert x.numel() == out.numel()
    if x.dtype not in _FLAT_DTYPES or x.dtype != out.dtype:
        from flag_gems.ops.hardswish import hardswish_out as _public

        return _public(x, out)

    inp = x.contiguous()
    n_total = out.numel()
    if n_total == 0:
        return out

    block, num_warps, grid_cap = _choose_launch(n_total, inp.element_size())
    if not out.is_contiguous():
        # Strided out cannot take flat stores; land the result in a fresh
        # contiguous buffer and copy back through out's strides
        # (silu_/hardswish_ strided-input precedent).
        tmp = torch.empty_like(inp)
        _launch_flat(
            hardswish_flat_kernel, (inp, tmp), n_total, block, num_warps, grid_cap
        )
        out.copy_(tmp)
        return out

    _launch_flat(hardswish_flat_kernel, (inp, out), n_total, block, num_warps, grid_cap)
    return out
